// The conflict log is recomputed from git, never stored: for every merge commit on the first-parent chain
// master..head, the files the automatic merge of its two parents conflicted on, classified.
import { gitOut, mergeTree } from "./git.mjs";
import { classifyFile } from "./mechanical.mjs";

export function conflictLogFor(cwd, master, head) {
  const merges = gitOut(cwd, ["rev-list", "--merges", "--first-parent", "--reverse", `${master}..${head}`], { allowFail: true })
    .split("\n")
    .filter(Boolean);
  const entries = new Map();
  for (const merge of merges) {
    const [, ours, theirs] = gitOut(cwd, ["rev-list", "--parents", "-n", "1", merge]).split(" ");
    if (!theirs) continue;
    for (const path of mergeTree(cwd, ours, theirs).files) {
      const c = classifyFile(path);
      entries.set(path, {
        path,
        kind: c.kind,
        ...(c.kind === "mechanical" ? { rule: c.rule } : {}),
        resolution: c.kind === "mechanical" ? resolutionFor(c) : "resolved by hand (see the resolution diff)",
      });
    }
  }
  return [...entries.values()];
}

function resolutionFor(c) {
  switch (c.action) {
    case "restore-master":
      return "kept the fork's copy (CI owns lockfile updates)";
    case "renumber-migrations":
      return "renumbered after the fork's last migration; journal rebuilt";
    case "regenerate":
      return `regenerated by the ${c.generator} generator`;
    default:
      return "settled by script";
  }
}
